async function saveAutosave():Promise<void>{try{await db.saveSong({id:'autosave-v6',name:'Autosave',code:editorView?.state.doc.toString()||code,updated:Date.now()})}catch{}}
async function loadLocalState():Promise<void>{const hosted=import.meta.env.PROD;try{savedSongs=await db.listSongs();const auto=savedSongs.find(s=>s.id==='autosave-v6')||savedSongs.find(s=>s.id==='autosave-v5');if(!hosted&&!location.hash&&auto){code=auto.code;savedSongs.sort((a,b)=>b.updated-a.updated)}storedSamples=await db.listSamples()}catch(error){status(`Local storage unavailable · ${(error as Error).message}`,true)}try{committedSource=hosted?STARTER:localStorage.getItem('scone-applied-code')||STARTER}catch{committedSource=STARTER}if(hosted)code=STARTER;dirty=code!==committedSource;initializeEditor();renderSampleChips();renderBank();renderSavedSongs()}
async function ensureSampleLoaded(record:SampleRecord):Promise<void>{if(audio.sampleNames().includes(record.name))return;await audio.decodeSample(record.name,record.blob)}
async function addSample(name:string,blob:Blob):Promise<void>{if(!blob.size){status('The recording was empty.',true);return}try{await audio.start();const raw=await audio.context!.decodeAudioData(await blob.arrayBuffer()),trimmed=trimAndEncodeWav(raw),id=crypto.randomUUID(),record:SampleRecord={id,name,blob:trimmed,created:Date.now()};await db.saveSample(record);audio.addSample(name,await audio.context!.decodeAudioData(await trimmed.arrayBuffer()));storedSamples=await db.listSamples();status(`Saved ${name} · connect it to a pattern to play`);renderSampleChips();renderBank()}catch(error){status(`Could not decode audio · ${(error as Error).message}`,true)}}
function sampleName():string{let n=1;while(storedSamples.some(s=>s.name===`sample${n}`))n++;return`sample${n}`}
function renderSampleChips():void{const count=document.querySelector<HTMLElement>('#sound-count');if(count)count.textContent=String(storedSamples.length)}
async function persistWavetables():Promise<void>{for(const [name] of waveDefinitions){if(storedSamples.some(sample=>sample.name===name))continue;const buffer=audio.sampleBuffer(name);if(!buffer)continue;try{const record:SampleRecord={id:crypto.randomUUID(),name,blob:trimAndEncodeWav(buffer),created:Date.now()};await db.saveSample(record);storedSamples.push(record)}catch{}}renderSampleChips();renderBank()}
function renderBank():void{
  const root=document.querySelector<HTMLDivElement>('#bank-content');if(!root)return;root.innerHTML=storedSamples.map(s=>`<div class="bank-row" data-sample="${escapeHtml(s.id)}"><div class="bank-row-head"><span class="sample-name">${escapeHtml(s.name)}</span><span><button class="bank-action" data-action="play">▶</button><button class="bank-action" data-action="rename">rename</button><button class="bank-action" data-action="delete">×</button></span></div><canvas class="waveform" data-wave="${escapeHtml(s.id)}" width="340" height="38"></canvas><div class="trim"><input type="range" min="0" max="49" value="0" data-trim="start"><input type="range" min="51" max="100" value="100" data-trim="end"></div><button class="bank-action" data-action="trim">apply trim</button></div>`).join('')||'<p>Upload an audio snippet or define a waveform in the editor.</p>'
  root.querySelectorAll<HTMLCanvasElement>('canvas[data-wave]').forEach(c=>drawWave(c,storedSamples.find(s=>s.id===c.dataset.wave)?.blob))
}
async function drawWave(canvas:HTMLCanvasElement,blob?:Blob):Promise<void>{if(!blob)return;try{const Decoder=window.OfflineAudioContext||(window as typeof window&{webkitOfflineAudioContext?:typeof OfflineAudioContext}).webkitOfflineAudioContext;if(!Decoder)return;const decoder=new Decoder(1,1,44100),b=await decoder.decodeAudioData(await blob.arrayBuffer()),d=b.getChannelData(0),g=canvas.getContext('2d')!,w=canvas.width,h=canvas.height;g.clearRect(0,0,w,h);g.strokeStyle='#66716c';g.beginPath();for(let x=0;x<w;x++){const i=Math.floor(x*d.length/w),end=Math.max(i+1,Math.floor((x+1)*d.length/w));let lo=1,hi=-1;for(let j=i;j<end;j++){lo=Math.min(lo,d[j]);hi=Math.max(hi,d[j])}g.moveTo(x,(1-hi)*h/2);g.lineTo(x,(1-lo)*h/2)}g.stroke()}catch{}}
function renderSavedSongs():void{const root=document.querySelector<HTMLDivElement>('#bank-content');if(!root)return;const existing=root.innerHTML;const rows=savedSongs.filter(s=>s.id!=='autosave').slice(0,12).map(s=>`<div class="song-row"><button class="bank-action" data-song="${escapeHtml(s.id)}">${escapeHtml(s.name)}</button><small>${new Date(s.updated).toLocaleDateString()}</small></div>`).join('');if(rows)root.insertAdjacentHTML('beforeend',`<h3>Saved songs</h3>${rows}`)}
function openBank():void{$('#bank-panel')!.classList.toggle('open');renderBank();renderSavedSongs()}
function bytesToBase64(buffer:ArrayBuffer):string{const bytes=new Uint8Array(buffer);let text='';for(let i=0;i<bytes.length;i+=0x8000)text+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(text)}
function base64ToBlob(value:string,type:string):Blob{const binary=atob(value),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);return new Blob([bytes],{type})}
function download(name:string,blob:Blob):void{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)}
function sampleSlice(buffer:AudioBuffer,start:number,end:number):AudioBuffer{const from=Math.floor(buffer.length*Math.max(0,Math.min(.99,start))),to=Math.max(from+1,Math.floor(buffer.length*Math.max(.01,Math.min(1,end)))),result=audio.context!.createBuffer(buffer.numberOfChannels,to-from,buffer.sampleRate);for(let c=0;c<buffer.numberOfChannels;c++)result.copyToChannel(buffer.getChannelData(c).subarray(from,to),c);return result}

async function beginRecording(source:'mic'|'tab'|'output'):Promise<void>{
  if(recorder?.state==='recording'){recorder.stop();return}
  try{
    await audio.start();let stream:MediaStream
    if(source==='mic'){micStream??=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false},video:false});stream=micStream;ensureMicAnalyser()}
    else if(source==='tab'){if(!navigator.mediaDevices.getDisplayMedia)throw new Error('Tab audio capture is unavailable in this browser.');stream=await navigator.mediaDevices.getDisplayMedia({video:true,audio:true});if(!stream.getAudioTracks().length)throw new Error('Choose a browser tab and enable “Share tab audio”.');}
    else{await audio.start();stream=audio.captureDestination!.stream}
    recordedStream=stream;recordedChunks=[];captureName=sampleName();const mime=['audio/webm;codecs=opus','audio/webm','audio/ogg'].find(m=>MediaRecorder.isTypeSupported(m));recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined)
    recorder.ondataavailable=e=>{if(e.data.size)recordedChunks.push(e.data)}
    recorder.onstop=async()=>{const blob=new Blob(recordedChunks,{type:recorder?.mimeType||'audio/webm'});for(const track of stream.getTracks())track.stop();if(source==='mic'){audio.disconnectMicrophone();micStream=null}recordedStream=null;$('#rec-mic')!.classList.remove('recording');$('#rec-tab')!.classList.remove('recording');$('#rec-output')!.classList.remove('recording');$('#rec-mic')!.textContent='● REC mic';$('#rec-tab')!.textContent='● REC tab';$('#rec-output')!.textContent='↻ REC output';await addSample(captureName,blob);recorder=null}
    recorder.start(200);const button=source==='mic'?'#rec-mic':source==='tab'?'#rec-tab':'#rec-output';$(button)!.classList.add('recording');$(button)!.textContent='■ STOP REC';status(`Recording ${source} audio · press again to finish`)
  }catch(error){status((error as Error).message,true)}
}

$('#play')!.addEventListener('click',()=>{if(!running)void startTransport()});$('#pause')!.addEventListener('click',pauseTransport);$('#apply-code')!.addEventListener('click',()=>void applyCodeChanges())
document.querySelectorAll<HTMLButtonElement>('[data-axis]').forEach(button=>button.addEventListener('click',()=>{labAxis=button.dataset.axis as typeof labAxis;labFitR=null;document.querySelectorAll('[data-axis]').forEach(node=>node.classList.toggle('active',node===button));setLabButton();updateLab()}))
document.querySelectorAll<HTMLButtonElement>('[data-mode]').forEach(button=>button.addEventListener('click',()=>{const next=button.dataset.mode as typeof labMode;if(next==='draw'&&labMode==='equation')labData=labPreview();labMode=next;document.querySelectorAll('[data-mode]').forEach(node=>node.classList.toggle('active',node===button));updateLab()}))
$('#lab-name')!.addEventListener('input',event=>{if(!labDefinition)return;const name=(event.currentTarget as HTMLInputElement).value.trim();if(name)labDefinition.soundName=name;$('#lab-title')!.textContent=`${labDefinition.variable} · ${labDefinition.soundName} · ${labAxis}`});$('#lab-equation')!.addEventListener('input',drawLab);$('#lab-equation')!.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();commitLabEquation();(e.target as HTMLInputElement).blur()}});$('#lab-graph')!.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();if(labMode==='equation')labData=labPreview();labMode='draw';document.querySelectorAll('[data-mode]').forEach(node=>node.classList.toggle('active',(node as HTMLElement).dataset.mode==='draw'));updateLab();drawingLab=true;lastLabPoint=null;const canvas=e.currentTarget as HTMLCanvasElement;try{canvas.setPointerCapture(e.pointerId)}catch{}drawAt(e)});$('#lab-graph')!.addEventListener('pointermove',e=>{if(drawingLab)drawAt(e)});$('#lab-graph')!.addEventListener('pointerup',finishLabDrawing);$('#lab-graph')!.addEventListener('pointercancel',finishLabDrawing);$('#lab-graph')!.addEventListener('lostpointercapture',finishLabDrawing);$('#lab-close')!.addEventListener('click',()=>$('#lab-panel')!.classList.add('hidden'));document.addEventListener('pointerdown',e=>{const panel=$('#lab-panel');if(!panel?.classList.contains('hidden')&&!panel.contains(e.target as Node))panel.classList.add('hidden')});updateLab()
$('#fullscreen')!.addEventListener('click',async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen()}catch{status('Fullscreen is unavailable here',true)}})
$('#lab-insert')!.addEventListener('click',()=>commitLabEquation())

document.querySelector('#bank-content')?.addEventListener('click',async e=>{const target=e.target as HTMLElement,button=target.closest<HTMLButtonElement>('[data-action]'),song=target.closest<HTMLButtonElement>('[data-song]');if(song){const r=savedSongs.find(s=>s.id===song.dataset.song);if(r&&editorView)editorView.dispatch({changes:{from:0,to:editorView.state.doc.length,insert:r.code}});return}if(!button)return;const row=button.closest<HTMLElement>('[data-sample]'),record=storedSamples.find(s=>s.id===row?.dataset.sample);if(!record)return;const action=button.dataset.action
  if(action==='play'){try{await audio.start();await ensureSampleLoaded(record);audio.play(record.name);status(`Playing ${record.name}`)}catch(error){status((error as Error).message,true)}}
  if(action==='rename'){const name=prompt('Rename sample',record.name);if(name){audio.removeSample(record.name);const next={...record,name};await db.saveSample(next);await audio.decodeSample(name,record.blob);storedSamples=await db.listSamples();renderBank();renderSampleChips()}}
  if(action==='delete'){if(confirm(`Delete ${record.name}?`)){await db.deleteSample(record.id);audio.removeSample(record.name);storedSamples=await db.listSamples();renderBank();renderSampleChips()}}
  if(action==='trim'){const a=Number(row?.querySelector<HTMLInputElement>('[data-trim=start]')?.value||0)/100,b=Number(row?.querySelector<HTMLInputElement>('[data-trim=end]')?.value||100)/100;try{await audio.start();const raw=await audio.context!.decodeAudioData(await record.blob.arrayBuffer()),cut=sampleSlice(raw,a,b),blob=trimAndEncodeWav(cut);audio.removeSample(record.name);await audio.decodeSample(record.name,blob);await db.saveSample({...record,blob});storedSamples=await db.listSamples();renderBank();status(`Trimmed ${record.name}`)}catch(error){status((error as Error).message,true)}}
})
document.querySelector('#bank-content')?.addEventListener('input',e=>{const input=(e.target as HTMLInputElement);if(input.dataset.trim){const row=input.closest<HTMLElement>('[data-sample]');if(row){const start=Number(row.querySelector<HTMLInputElement>('[data-trim=start]')?.value||0),end=Number(row.querySelector<HTMLInputElement>('[data-trim=end]')?.value||100);if(start>=end)(input.dataset.trim==='start'?row.querySelector<HTMLInputElement>('[data-trim=start]')!:row.querySelector<HTMLInputElement>('[data-trim=end]')!).value=String(input.dataset.trim==='start'?Math.max(0,end-1):Math.min(100,start+1))}}})

window.addEventListener('keydown',e=>{const key=normalizeKey(e),editing=(e.target as HTMLElement)?.closest('.cm-editor')!==null;if(key==='escape')$('#lab-panel')!.classList.add('hidden');if(!editing){if(!pressedKeys.has(key))justPressedKeys.add(key);pressedKeys.add(key)}})
window.addEventListener('keyup',e=>pressedKeys.delete(normalizeKey(e)))
window.addEventListener('blur',()=>{pressedKeys.clear();justPressedKeys.clear()})

void loadLocalState();void drawSoundPanels()
